    static AddScalarToRef(v, scalar, ref) {
        const { x, y } = v;
        ref.x = x + scalar;
        ref.y = y + scalar;
        return ref;
    }
    static Subtract(v1, v2) {
        return this.SubtractToRef(v1, v2, this.Create());
    }
